150	
151	  const handleAiGenerate = async () => {
152	    if (!aiPrompt) return;
153	    try {
154	      await aiGenerate.mutateAsync({ projectId, data: { prompt: aiPrompt, count: aiCount } });
155	      setAiPrompt(""); setShowAIPanel(false); refresh();
156	      toast({ title: "Components generated" });
157	    } catch (err) {
158	      toast({ title: "AI generate failed", description: errMsg(err), variant: "destructive" });
159	    }
160	  };
161	
162	  const handleAddEntity = async (e: React.FormEvent) => {
163	    e.preventDefault();
164	    if (!newEntity.name) return;
165	    try {
166	      await createEntity.mutateAsync({
167	        projectId,
168	        data: {
169	          name: newEntity.name, type: newEntity.type,
170	          subtype: newEntity.subtype || undefined,
171	          description: newEntity.description || undefined,
172	          stats: newEntity.stats || undefined,
173	          relatedTo: newEntity.relatedTo || undefined,
174	          parentEntityId: newEntity.parentEntityId || undefined,
175	        },
176	      });
177	      setNewEntity({ name: "", type: "Card", subtype: "", description: "", stats: "", relatedTo: "" });
178	      setShowAddForm(false);
179	      refresh();
180	    } catch (err) {
181	      toast({ title: "Could not create component", description: errMsg(err), variant: "destructive" });
182	    }
183	  };
184	
185	  const toggleExpand = (id: number) =>
186	    setExpandedIds((prev) => { const s = new Set(prev); s.has(id) ? s.delete(id) : s.add(id); return s; });
187	
188	  const toggleGroup = (type: string) =>
189	    setCollapsedGroups((prev) => { const s = new Set(prev); s.has(type) ? s.delete(type) : s.add(type); return s; });
190	
191	  // Derived data
192	  const { topLevel, childrenByParent, decks } = useMemo(() => {
193	    const all = entities ?? [];
194	    const childrenByParent: Record<number, Entity[]> = {};
195	    const childIds = new Set<number>();
196	    all.forEach((e) => {
197	      if (e.parentEntityId) {
198	        childIds.add(e.id);
199	        if (!childrenByParent[e.parentEntityId]) childrenByParent[e.parentEntityId] = [];
200	        childrenByParent[e.parentEntityId].push(e);
201	      }
202	    });
203	    return {
204	      topLevel: all.filter((e) => !childIds.has(e.id)),
205	      childrenByParent,
206	      decks: new Set(all.filter((e) => e.type === "Deck").map((e) => e.id)),
207	    };
208	  }, [entities]);
209	
210	  const typeCounts = useMemo(() => {
211	    const out: Record<string, number> = {};
212	    topLevel.forEach((e) => { out[e.type] = (out[e.type] || 0) + 1; });
213	    return out;
214	  }, [topLevel]);
215	
216	  const statusCounts = useMemo(() => {
217	    const out: Record<string, number> = {};
218	    topLevel.forEach((e) => { const s = e.status ?? "draft"; out[s] = (out[s] || 0) + 1; });
219	    return out;
220	  }, [topLevel]);
221	
222	  // Available subtypes for the current type filter
223	  const availableSubtypes = useMemo(() => {
224	    if (filterType === "all") return [];
225	    const subs = new Set<string>();
226	    topLevel.filter((e) => e.type === filterType && e.subtype).forEach((e) => subs.add(e.subtype!));
227	    return Array.from(subs);
228	  }, [topLevel, filterType]);
229	
230	  const filtered = useMemo(() => {
231	    let arr = topLevel;
232	    if (filterType !== "all") arr = arr.filter((e) => e.type === filterType);
233	    if (filterStatus !== "all") arr = arr.filter((e) => (e.status ?? "draft") === filterStatus);
234	    if (filterSubtype !== "all") arr = arr.filter((e) => e.subtype === filterSubtype);
235	    if (search.trim()) {
236	      const q = search.trim().toLowerCase();
237	      arr = arr.filter((e) =>
238	        e.name.toLowerCase().includes(q) ||
239	        e.description?.toLowerCase().includes(q) ||
240	        e.subtype?.toLowerCase().includes(q),
241	      );
242	    }
243	    return arr;
244	  }, [topLevel, filterType, filterStatus, filterSubtype, search]);
245	
246	  const grouped = useMemo(() => {
247	    if (filterType !== "all") return null;
248	    const map = new Map<string, Entity[]>();
249	    filtered.forEach((e) => {
250	      if (!map.has(e.type)) map.set(e.type, []);
251	      map.get(e.type)!.push(e);
252	    });
253	    return map;
254	  }, [filtered, filterType]);
255	
256	  // Sync local order from server whenever filtered changes (but not during active drag)
257	  // Uses server displayOrder for initial sort, falling back to filtered order (createdAt desc)
258	  useEffect(() => {
259	    if (draggedEntityId === null) {
260	      const sorted = [...filtered].sort((a, b) => {
261	        const oa = a.displayOrder ?? Infinity;
262	        const ob = b.displayOrder ?? Infinity;
263	        return oa - ob;
264	      });
265	      setLocalEntityOrder(sorted.map((e) => e.id));
266	    }
267	  }, [filtered, draggedEntityId]);
268	
269	  // Apply local drag order to filtered list
270	  const orderedFiltered = useMemo(() => {
271	    if (localEntityOrder.length === 0) return filtered;
272	    const orderMap = new Map(localEntityOrder.map((id, i) => [id, i]));
273	    return [...filtered].sort((a, b) => {
274	      const ia = orderMap.has(a.id) ? orderMap.get(a.id)! : Infinity;
275	      const ib = orderMap.has(b.id) ? orderMap.get(b.id)! : Infinity;
276	      return ia - ib;
277	    });
278	  }, [filtered, localEntityOrder]);
279	
280	  const handleEntityDragStart = (id: number, e: React.DragEvent) => {
281	    e.dataTransfer.effectAllowed = "move";
282	    setDraggedEntityId(id);
283	    dragOverEntityIdRef.current = null;
284	    document.body.style.cursor = "grabbing";
