function parseRelatedTo(raw: string | null | undefined): string[] {
  if (!raw) return [];
  return raw.split(/[,;\n]/).map((s) => s.trim()).filter(Boolean);
}

interface RelEntry { verb?: string; name: string; }

function parseRelationships(raw: string | null | undefined): RelEntry[] {
  if (!raw) return [];
  return raw.split(/[,;\n]/).map((s) => s.trim()).filter(Boolean).map((s) => {
    const m = s.match(/^([a-z-]+):(.+)$/i);
    if (m && (RELATIONSHIP_VERBS as readonly string[]).includes(m[1].toLowerCase())) {
      return { verb: m[1].toLowerCase(), name: m[2].trim() };
    }
    return { name: s };
  });
}

function serializeRelationships(rels: RelEntry[]): string {
  return rels.map((r) => r.verb ? `${r.verb}:${r.name}` : r.name).join(", ");
}

