372	                            <DropdownMenuItem onClick={() => { deleteTask.mutate({ projectId, taskId: task.id }); qc.invalidateQueries({ queryKey: getListRichTasksQueryKey(projectId) }); }} className="text-destructive focus:text-destructive"><Trash2 className="h-4 w-4 mr-2" /> Delete</DropdownMenuItem>
373	                          </DropdownMenuContent>
374	                        </DropdownMenu>
375	                      </td>
376	                    </tr>
377	                  ))}
378	                </tbody>
379	              </table>
380	            </div>
