1	import { useEffect } from "react";
2	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
3	import type {
4	  RichTask, SubTask, TaskComment, ActivityLogEntry,
5	  ProjectShare, NotificationItem, PresenceUser,
6	  TaskFilter, TaskSort, ProjectRole,
7	} from "@/lib/collaboration-types";
8	import * as api from "@/lib/collaboration-api";
9	
10	// ─── Tasks ────────────────────────────────────────────────────────────────────
11	
12	export function getListRichTasksQueryKey(projectId: number, filter?: TaskFilter, sort?: TaskSort) {
13	  return ["rich-tasks", projectId, filter, sort];
14	}
15	
16	export function useListRichTasks(projectId: number, filter?: TaskFilter, sort?: TaskSort) {
17	  return useQuery({
18	    queryKey: getListRichTasksQueryKey(projectId, filter, sort),
19	    queryFn: () => api.listTasks(projectId, filter, sort),
20	    staleTime: 30_000,
21	  });
22	}
23	
24	export function useCreateRichTask() {
25	  const qc = useQueryClient();
26	  return useMutation({
27	    mutationFn: ({ projectId, data }: { projectId: number; data: Partial<RichTask> }) =>
28	      api.createTask(projectId, data),
29	    onSuccess: (_, vars) => {
30	      qc.invalidateQueries({ queryKey: ["rich-tasks", vars.projectId] });
31	      qc.invalidateQueries({ queryKey: ["activity", vars.projectId] });
32	    },
33	  });
34	}
35	
36	export function useUpdateRichTask() {
37	  const qc = useQueryClient();
38	  return useMutation({
39	    mutationFn: ({ projectId, taskId, data }: { projectId: number; taskId: number; data: Partial<RichTask> }) =>
40	      api.updateTask(projectId, taskId, data),
41	    onSuccess: (_, vars) => {
42	      qc.invalidateQueries({ queryKey: ["rich-tasks", vars.projectId] });
43	      qc.invalidateQueries({ queryKey: ["task-detail", vars.taskId] });
44	      qc.invalidateQueries({ queryKey: ["activity", vars.projectId] });
45	    },
46	  });
47	}
48	
49	export function useDeleteRichTask() {
50	  const qc = useQueryClient();
51	  return useMutation({
52	    mutationFn: ({ projectId, taskId }: { projectId: number; taskId: number }) =>
53	      api.deleteTask(projectId, taskId),
54	    onSuccess: (_, vars) => {
55	      qc.invalidateQueries({ queryKey: ["rich-tasks", vars.projectId] });
56	      qc.invalidateQueries({ queryKey: ["activity", vars.projectId] });
57	    },
58	  });
59	}
60	
61	// ─── Subtasks ─────────────────────────────────────────────────────────────────
62	
63	export function getListSubtasksQueryKey(taskId: number) {
64	  return ["subtasks", taskId];
65	}
66	
67	export function useListSubtasks(taskId: number, projectId?: number) {
68	  // Register the taskId→projectId mapping so the API client can build URLs
69	  useEffect(() => {
70	    if (projectId && taskId) api.registerTaskProject(taskId, projectId);
71	  }, [taskId, projectId]);
72	
73	  return useQuery({
74	    queryKey: getListSubtasksQueryKey(taskId),
75	    queryFn: () => api.listSubtasks(taskId, projectId),
76	    enabled: taskId > 0,
77	    staleTime: 30_000,
78	  });
79	}
80	
81	export function useCreateSubtask() {
82	  const qc = useQueryClient();
83	  return useMutation({
84	    mutationFn: ({ taskId, title, projectId }: { taskId: number; title: string; projectId?: number }) => {
85	      if (projectId) api.registerTaskProject(taskId, projectId);
86	      return api.createSubtask(taskId, title);
